local function expect(label, value) return T.expect(label, value, true) end
expect('buffer installed', type(buffer) == 'table' and rawequal(buffer, builtin.buffer))
local b = buffer.create(5)
T.value('initial', {b:head(), b:tail(), b:capacity(), b:remaining(), b:order(), b:to_string(), typeof(b)})
expect('initial is not readable', b:capacity() == 5 and b:remaining() == 0)
T.call('empty read', function() return b:read_u8() end)
T.call('head setter nil', function() return b:head(0) end)
T.call('tail setter nil', function() return b:tail(5) end)
expect('zero fill', b:read_string(5) == string.rep('\0', 5))
T.call('reset no values', function() return b:reset() end)
T.call('reserve no values', function() return b:reserve(8) end)
expect('growth exact and cursors unchanged', b:capacity() == 8 and b:head() == 0 and b:tail() == 0)
T.call('reserve overflow', function() b:reserve(-1) end)
T.call('constructor wrong type', function() buffer.create(false) end)
T.call('wrap wrong type', function() buffer.wrap(17) end)
T.value('nil defaults', {buffer.create():capacity(), buffer.create(nil):capacity(), b:head(nil), b:tail(nil), b:order(nil)})
for _,order in ipairs({'little', 'big'}) do
  local p = buffer.create()
  T.call(order..' order setter nil', function() return p:order(order) end)
  p:write_u8(255); p:write_i8(-128); p:write_bool(false); p:write_bool(true)
  p:write_u16(65535); p:write_i16(-32768); p:write_u32(4294967295); p:write_i32(-2147483648)
  p:write_u64(-1); p:write_i64(-9223372036854775807 - 1)
  p:write_f16(1.5); p:write_f32(-2.25); p:write_f64(3.125)
  T.value(order..' encoded', p:to_string())
  local values = {p:read_u8(), p:read_i8(), p:read_bool(), p:read_bool(), p:read_u16(), p:read_i16(), p:read_u32(), p:read_i32(), p:read_u64(), p:read_i64(), p:read_f16(), p:read_f32(), p:read_f64()}
  T.value(order..' decoded', values)
  expect(order..' values', values[1] == 255 and values[2] == -128 and not values[3] and values[4] and values[5] == 65535 and values[6] == -32768 and values[7] == 4294967295 and values[8] == -2147483648 and values[9] == -1 and values[10] == -9223372036854775807 - 1 and values[11] == 1.5 and values[12] == -2.25 and values[13] == 3.125 and p:remaining() == 0)
  T.call(order..' exhausted', function() p:read_f64() end)
end
local s = buffer.wrap('a\0\255\128z')
expect('binary wrap', s:capacity() == 5 and s:to_string() == 'a\0\255\128z')
expect('counted strings, no terminator', s:read_string(3) == 'a\0\255' and s:read_string(0) == '' and s:head() == 3)
s:write_string('\0!')
expect('wrap writable appends raw', s:to_string() == '\128z\0!')
T.call('string missing length', function() s:read_string() end)
T.call('string numeric write refused', function() s:write_string(42) end)
s:tail(2)
expect('head exceeds tail', s:head() == 3 and s:remaining() == 0 and s:to_string() == '' and tostring(s) == '')
T.call('zero read checks bounds', function() s:read_string(0) end)
T.call('zero skip checks bounds', function() s:skip(0) end)
T.call('head beyond tail', function() s:head(3) end)
T.call('tail beyond storage', function() s:tail(8) end)
s:reset(); s:tail(7)
expect('reset retains bytes', s:to_string() == 'a\0\255\128z\0!')
T.call('order default refused', function() s:order('default') end)
T.call('order binary refused', function() s:order('\255') end)
T.call('unknown field', function() return s.unknown end)
T.call('unknown assignment', function() s.unknown = 1 end)
T.call('missing receiver', function() s.head() end)
T.call('invalid receiver', function() s.head(false, 'bad') end)
T.call('u8 conversion', function() s:write_u8(256) end)
T.call('bool conversion', function() s:write_bool(1) end)
T.call('numeric UTF8 conversion', function() s:write_i16('\255') end)
local floats = buffer.create()
for _,width in ipairs({'f16','f32','f64'}) do
  T.call(width..' numeric inf refused', function() floats['write_'..width](floats, math.huge) end)
  T.call(width..' numeric nan refused', function() floats['write_'..width](floats, 0/0) end)
  floats['write_'..width](floats, 'inf')
  floats['write_'..width](floats, '-0')
  expect(width..' string inf and negative zero', floats['read_'..width](floats) == math.huge and 1/floats['read_'..width](floats) == -math.huge)
end
T.call('f16 range before rounding', function() floats:write_f16(65505) end)
floats:write_f16('65505'); expect('f16 string parser', floats:read_f16() == 65504)
floats:write_f16(2^-24); expect('f16 subnormal', floats:read_f16() == 2^-24)
local src = buffer.wrap('abcdef'); src:skip(1)
local dst = buffer.wrap('X')
T.call('distinct copy no values', function() return dst:copy(src, 1, 3) end)
expect('copy head relative, source unchanged', dst:to_string() == 'Xcde' and src:head() == 1)
T.call('copy default length not adjusted for offset', function() dst:copy(src, 1) end)
expect('copy failure unchanged', dst:to_string() == 'Xcde')
T.call('self copy no values', function() return src:copy(src, 1, 3) end)
expect('self copy source and destination', src:head() == 1 and src:to_string() == 'bcdefcde')
local overlap = buffer.wrap('abc'); overlap:copy(overlap); expect('self copy growth', overlap:to_string() == 'abcabc')
local closed = buffer.wrap('closed'); closed:close()
T.call('closed source eager remaining', function() dst:copy(closed, 0, 0) end)
T.call('closed self eager remaining', function() closed:copy(closed, 0, 0) end)
T.call('source bounds precede destination closed', function() closed:copy(dst, 100, 1) end)
T.call('copy bad source before state', function() closed:copy(false) end)
T.call('copy bad offset before state', function() closed:copy(dst, false) end)
T.call('copy bad length before state', function() closed:copy(dst, nil, false) end)
for _,name in ipairs({'head','tail','remaining','capacity','reset','reserve','order','skip','read_u8','read_string','write_u8','write_string','to_string'}) do
  T.call('closed '..name, function() return closed[name](closed, 0) end)
end
T.call('closed invalid order before state', function() closed:order('default') end)
T.call('closed invalid write before state', function() closed:write_u16(false) end)
T.call('closed tostring', function() return tostring(closed) end)
T.call('repeated close no values', function() return closed:close() end)
expect('no extra metamethods', getmetatable(dst) == false and not pcall(function() return #dst end))
